package tui

import (
	"context"
	"time"

	tea "charm.land/bubbletea/v2"
	"github.com/ishansain/gotui"
	"github.com/ishansain/gotui/list"
	"github.com/ishansain/gotui/statusbar"
	"github.com/ishansain/gotui/tabs"
	"github.com/ishansain/gotui/viewport"

	"nice-llama-server/internal/config"
	"nice-llama-server/internal/controller"
)

const (
	statePollInterval = 1200 * time.Millisecond
	logPollInterval   = 450 * time.Millisecond
	maxVisibleLogs    = 2000
)

type focusArea int

const (
	focusModelList focusArea = iota
	focusDetailName
	focusDetailArgs
)

type listItemKind int

const (
	listItemModelGroup listItemKind = iota
	listItemBookmark
)

type listItem struct {
	kind       listItemKind
	groupKey   string
	modelPath  string
	label      string
	bookmarkID string
	degraded   bool
}

func (i listItem) key() string {
	if i.kind == listItemBookmark {
		return "bookmark:" + i.bookmarkID
	}
	return "group:" + i.modelPath
}

type model struct {
	ctx               context.Context
	client            *controller.Client
	theme             gotui.Theme
	styles            styles
	width             int
	height            int
	focus             focusArea
	snapshot          config.Snapshot
	selectedKey       string
	modelList         list.Model
	logs              []config.LogEntry
	lastSeq           int64
	logScrollX        int
	stateReady        bool
	errorMessage      string
	flashMessage      string
	editor            *bookmarkEditor
	confirmDelete     bool
	followTailEnabled bool
	footer            statusbar.Model
	tabs              tabs.Model
	logView           viewport.Model
}

type stateMsg struct {
	snapshot config.Snapshot
	err      error
}

type logsMsg struct {
	entries []config.LogEntry
	err     error
}

type actionMsg struct {
	snapshot    config.Snapshot
	selectedKey string
	note        string
	err         error
	clearEditor bool
	focus       focusArea
}

type pollStateMsg struct{}
type pollLogsMsg struct{}

func newModel(ctx context.Context, client *controller.Client) *model {
	m := &model{
		ctx:               ctx,
		client:            client,
		theme:             gotui.Dark(),
		styles:            newStyles(gotui.Dark()),
		width:             100,
		height:            34,
		focus:             focusModelList,
		followTailEnabled: true,
		footer:            statusbar.New(gotui.Dark()),
		logView:           viewport.New(gotui.Dark()),
	}
	m.tabs = tabs.New(gotui.Dark())
	m.tabs.SetTabs(tabs.Tab{ID: "bookmarks", Label: "Bookmarks"}, tabs.Tab{ID: "logs", Label: "Logs"})
	m.modelList = list.New(gotui.Dark())
	return m
}

func (m *model) Init() tea.Cmd {
	return tea.Batch(
		fetchStateCmd(m.ctx, m.client),
		fetchLogsCmd(m.ctx, m.client, 0),
		scheduleStatePoll(),
		scheduleLogPoll(),
	)
}

func (m *model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.footer.SetSize(msg.Width, 1)
		m.tabs.SetSize(msg.Width, 1)
		m.modelList.SetSize(msg.Width/2, msg.Height-10)
		return m, nil
	case stateMsg:
		if msg.err != nil {
			m.errorMessage = msg.err.Error()
			return m, nil
		}
		m.stateReady = true
		m.snapshot = msg.snapshot
		m.syncSelection()
		return m, nil
	case logsMsg:
		if msg.err != nil {
			m.errorMessage = msg.err.Error()
			return m, nil
		}
		if len(msg.entries) > 0 {
			wasAtBottom := m.logView.AtBottom()
			m.logs = append(m.logs, msg.entries...)
			if len(m.logs) > maxVisibleLogs {
				m.logs = append([]config.LogEntry(nil), m.logs[len(m.logs)-maxVisibleLogs:]...)
			}
			m.lastSeq = msg.entries[len(msg.entries)-1].Seq
			if m.followTailEnabled && wasAtBottom {
				m.logView.GotoBottom()
			}
		}
		return m, nil
	case actionMsg:
		if msg.err != nil {
			m.errorMessage = msg.err.Error()
			return m, tea.Batch(fetchStateCmd(m.ctx, m.client), fetchLogsCmd(m.ctx, m.client, m.lastSeq))
		}
		m.errorMessage = ""
		m.flashMessage = msg.note
		m.snapshot = msg.snapshot
